    const fleetStats=overview.fleet||timeseries.fleet?.stats||{},online=allNodes.filter(node=>/online|active|healthy/i.test(node.status||'')).length,totalClients=Number(fleetStats.total??allNodes.length),degraded=allNodes.filter(node=>/degraded|error/i.test(node.status||'')||(node.issues||[]).length).length;
    const selectedMetrics=selectedNodes.map(node=>node.metrics||{}),liveReadRate=streamFiles.reduce((total,item)=>total+Number(item.read_lines_per_second||0),0),liveOutputRate=streamFiles.reduce((total,item)=>total+Number(item.normalized_per_second||0),0),liveQuarantineRate=streamFiles.reduce((total,item)=>total+Number(item.quarantined_per_second||0),0);
    const backpressured=streamFiles.filter(item=>item.backpressure).length,queueDepth=streamFiles.reduce((total,item)=>total+Number(item.queue_depth||0),0),queueCapacity=streamFiles.reduce((total,item)=>total+Number(item.queue_capacity||0),0);
    const nsToMs=value=>Number(value||0)/1000000,pipeline={read:streamFiles.reduce((total,item)=>total+nsToMs(item.read_duration_ns),0),parse:streamFiles.reduce((total,item)=>total+nsToMs(item.parse_duration_ns),0),output:streamFiles.reduce((total,item)=>total+nsToMs(item.output_duration_ns),0)};pipeline.total=pipeline.read+pipeline.parse+pipeline.output;
    const pipelineBar=(label,value,color)=>`<div class="pipeline-row"><span>${esc(label)}</span><div><i style="width:${pipeline.total?Math.max(1,value/pipeline.total*100):0}%;background:${color}"></i></div><b>${value?`${value.toFixed(1)} ms`:'—'}</b></div>`;
    const familyMap=new Map();records.forEach(record=>{const key=String(record.service||record.parser_id||'unclassified').split('/')[0]||'unclassified';if(!familyMap.has(key))familyMap.set(key,{name:key,received:0,parsed:0,quarantine:0,errors:0,latency:0,latencyCount:0,trend:Array(12).fill(0)});const item=familyMap.get(key);item.received++;if(/normal|parsed|success|ok/i.test(`${record.route||''} ${record.result||''}`))item.parsed++;if(/quarantine|unknown/i.test(`${record.route||''} ${record.result||''}`))item.quarantine++;if((record.error_codes||[]).length||/error|fail/i.test(`${record.route||''} ${record.result||''}`))item.errors++;if(Number(record.latency_ms)>0){item.latency+=Number(record.latency_ms);item.latencyCount++;}const stamp=Date.parse(record.timestamp||record.processed_at||record.received_at||''),age=Number.isFinite(stamp)?Math.max(0,Date.now()-stamp):0,windowMinutes={"1h":60,"6h":360,"24h":1440,"7d":10080,"30d":43200}[state.dashboardRange]||60,bucketWidth=Math.max(1,windowMinutes*60000/12),itemIndex=Math.max(0,Math.min(11,11-Math.floor(age/bucketWidth)));item.trend[itemIndex]++;});
