    const clientRows=selectedNodes.map(node=>{const metrics=node.metrics||{},issues=node.issues||[];return `<tr><td><b>${esc(node.hostname||node.id||'Unknown')}</b><br><small class="mono">${esc(node.id||'—')}</small></td><td>${badge(node.status||'unknown')}<br><small>${time(node.last_seen)}</small></td><td>${Number(metrics.cpu_percent||0).toFixed(1)}%<div class="health-meter"><i style="width:${Math.min(100,Number(metrics.cpu_percent||0))}%"></i></div></td><td>${Number(metrics.memory_percent||0).toFixed(1)}%<div class="health-meter violet"><i style="width:${Math.min(100,Number(metrics.memory_percent||0))}%"></i></div></td><td>${Number(metrics.parse_rate_pct||0).toFixed(2)}%</td><td>${Number(metrics.parse_latency_ms||0).toFixed(2)} ms</td><td>${issues.length?`<span class="bad-text">${esc(issues.join(' · '))}</span>`:'No reported issues'}</td></tr>`;});
